function onSubmit() {
   //Type appropriate comment here, and begin script below
   var asset=g_form.getValue('type_of_asset');
   if (asset == 'computer'){
	g_form.setValue('assignment_group','41bbd81fc3e65a106dd09d777d013180');
	}
	else if(asset == 'printer'){
	g_form.setValue('assignment_group','65eb5cdbc3e65a106dd09d777d0131d6');
	}
	else if(asset == 'network gear'){
	g_form.setValue('assignment_group','b1db1c1fc3e65a106dd09d777d0131c8');
	}
	else if(asset == 'ups'){
	g_form.setValue('assignment_group','fefbd01fc3e65a106dd09d777d0131cc');
	}

}
